export type SchemaDefName = keyof typeof SCHEMA_DEFS;
export interface ValidationIssue { readonly path: string; readonly message: string }

type Node = { readonly [key: string]: unknown };
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const typeOk = (t: string, v: unknown): boolean => {
  switch (t) {
    case 'null': return v === null;
    case 'string': return typeof v === 'string';
    case 'boolean': return typeof v === 'boolean';
    case 'integer': return typeof v === 'number' && Number.isInteger(v);
    case 'number': return typeof v === 'number' && Number.isFinite(v);
    case 'array': return Array.isArray(v);
    case 'object': return isObj(v);
    default: return false;
  }
};

function check(node: Node, value: unknown, at: string, out: ValidationIssue[]): void {
  if (typeof node.$ref === 'string') {
    const name = node.$ref.replace('#/$defs/', '') as SchemaDefName;
    check(SCHEMA_DEFS[name] as unknown as Node, value, at, out);
    return;
  }
  if (Array.isArray(node.anyOf)) {
    const branches = node.anyOf as Node[];
    if (!branches.some((b) => { const tmp: ValidationIssue[] = []; check(b, value, at, tmp); return tmp.length === 0; })) {
      // Report the first non-null branch's issues: the most useful message.
      const main = branches.find((b) => b.type !== 'null') ?? branches[0];
      if (main) check(main, value, at, out);
    }
    return;
  }
  if (node['x-tml-kind'] === 'timestamp') {
    const ok = isObj(value) && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number';
    if (!ok) out.push({ path: at, message: 'expected a Firestore Timestamp' });
    return;
  }
  if (node.type !== undefined) {
    const types = Array.isArray(node.type) ? (node.type as string[]) : [node.type as string];
    if (!types.some((t) => typeOk(t, value))) { out.push({ path: at, message: `expected ${types.join(' or ')}` }); return; }
    if (value === null) return;
  }
  if (Array.isArray(node.enum) && !(node.enum as unknown[]).includes(value)) {
    out.push({ path: at, message: `expected one of ${(node.enum as unknown[]).map((x) => JSON.stringify(x)).join(', ')}` });
    return;
  }
  if (typeof value === 'string') {
    // PersonName counts grapheme clusters (x-tml-length), like Swift String.count; otherwise code points.
    const len = node['x-tml-length'] === 'graphemes' && typeof Intl !== 'undefined' && 'Segmenter' in Intl
      ? [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(value)].length
      : [...value].length;
    if (typeof node.minLength === 'number' && len < node.minLength) out.push({ path: at, message: `shorter than ${node.minLength}` });
    if (typeof node.maxLength === 'number' && len > node.maxLength) out.push({ path: at, message: `longer than ${node.maxLength}` });
    if (typeof node.pattern === 'string' && !new RegExp(node.pattern, 'u').test(value)) out.push({ path: at, message: 'does not match the pattern' });
  }
  if (typeof value === 'number') {
    if (typeof node.minimum === 'number' && value < node.minimum) out.push({ path: at, message: `below ${node.minimum}` });
    if (typeof node.maximum === 'number' && value > node.maximum) out.push({ path: at, message: `above ${node.maximum}` });
    if (typeof node.exclusiveMinimum === 'number' && value <= node.exclusiveMinimum) out.push({ path: at, message: `must be above ${node.exclusiveMinimum}` });
    if (typeof node.exclusiveMaximum === 'number' && value >= node.exclusiveMaximum) out.push({ path: at, message: `must be below ${node.exclusiveMaximum}` });
  }
  if (Array.isArray(value)) {
    if (isObj(node.items)) value.forEach((v, i) => check(node.items as Node, v, `${at}[${i}]`, out));
    if (node.uniqueItems === true && new Set(value.map((v) => JSON.stringify(v))).size !== value.length) out.push({ path: at, message: 'items must be unique' });
  }
  if (isObj(value) && isObj(node.properties)) {
    const props = node.properties as Record<string, Node>;
    for (const key of (node.required as readonly string[] | undefined) ?? []) {
      if (!(key in value)) out.push({ path: `${at}.${key}`, message: 'is required' });
    }
    for (const [key, v] of Object.entries(value)) {
      const prop = props[key];
      if (prop) check(prop, v, `${at}.${key}`, out);
      else if (node.additionalProperties === false) out.push({ path: `${at}.${key}`, message: 'is not allowed' });
    }
  }
}

/** Checks a value against one schema definition. An empty array means valid. */
export function validate(def: SchemaDefName, value: unknown): ValidationIssue[] {
  const out: ValidationIssue[] = [];
  check(SCHEMA_DEFS[def] as unknown as Node, value, '$', out);
  return out;
}

/** Like validate(), but throws a TypeError listing the issues. */
export function assertValid<T>(def: SchemaDefName, value: unknown): T {
  const issues = validate(def, value);
  if (issues.length) throw new TypeError(`${def}: ${issues.map((i) => `${i.path} ${i.message}`).join('; ')}`);
  return value as T;
}
